INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('smx8tnl440km9fj4tj0wsmx1jmf26dyi', '2025-Q2', 'Jun/2025', '2025-06-13T09:16'::timestamptz, 'Gelson da Rold', 'gelson da rold', 'PHARUS', 'Gabriel Oliveira', 7.0, 'Neutro', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Com base nesses últimos meses com o suporte do Gabriel devo dizer que tem válido a pena por conta do acompanhamento e atenção que tem dado a nossos projetos', 'Foi criado uma expectativa a certa dos consórcios contratados nem um controlado até o momento, se houve essa contemplação o retorno do investimento seria interessante de modo que tivéssemos lucro com auxílio da mentoria, isso que todos buscam', NULL, 'Ter retorno do investimento feito com os serviços de vocês', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'smx8tnl440km9fj4tj0wsmx1jmf26dyi', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('q995znu700s1gbxdve9q995zn2j67jcf', '2025-Q2', 'Jun/2025', '2025-06-13T09:20'::timestamptz, 'Elias Eulosio Dalla Corte', 'elias eulosio dalla corte', 'PHARUS', 'Hendrick Ramos', 8.0, 'Neutro', 10.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Perdi o vínculo com o projeto e preciso retomar', 'Na verdade acredito que a resposta seria Depende. O programa é muito bom, mas depende de qual é a situação atual do colega para eu indicar. Para alguns já indiquei.', 'Olha, no meu caso, entrei com a propaganda que era para ter independencia financeira em 7 anos. E a renda mínima para isso seria de 15000. Eu entrei "em cima da risca", porém isso não vai acontecer em 7 anos. Outra coisa é que o contrato era de 1 ano, talvez até ja passou um ano e já aproveito para agradecer que ainda estão me auxiliando. Mas 1 ano penso ser pouco por que algumas ações demoram para ter o retorno para tomar outras ações. Creio que o contrato deveria ser para mais anos ou em cima das reuniões e não mais em tempo, por exemplo, contrato vale para 12 reuniões com especialista.', NULL, 'Passei algumas melhorias solicitadas pelo meu advogado quanto a um contrato que me passaram de renda sintetica. O contrato ser em cima de número de rueniões e não em cima de tempo.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'q995znu700s1gbxdve9q995zn2j67jcf', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('wfwi5ak4577mrxdkzz89mwfwi5a0ra77', '2025-Q2', 'Jun/2025', '2025-06-13T09:25'::timestamptz, 'Larissa Xavier', 'larissa xavier', 'PHARUS', 'Luiz Henrique', 8.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Ainda estamos iniciando, portanto é um feedback, por hora, impreciso.', 'Tempo', NULL, 'Após implementar, acompanhamento de dúvidas semanais nos primeiros meses, depois quinzenal, depois mensal. Clareza nas operações, relatórios de progressão, acesso ao Adrian, mini curso com algum especialista (ex: Bitcoin, ou leilões, ao menos para explicar superficialmente como os processos são feitos-comk.nosso dinheiro está trabalhando). Incluir a PJ (no caso de sócios autônomos, como nós, ou um médico, adv- no caso dr "eupresa". E principalmente, acessória jurídica e contábil parceira para nós.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'wfwi5ak4577mrxdkzz89mwfwi5a0ra77', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('6mit0a3ll0lqiv4936mito0sv17ma715', '2025-Q2', 'Jun/2025', '2025-06-13T09:28'::timestamptz, 'Evandro Barbosa', 'evandro barbosa', 'PHARUS', 'Hendrick Ramos', 0.0, 'Detrator', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'Por enquanto o programa já está tendo utilidade alguma.', 'Conseguir alavancar com o imóvel próprio, essa foi a promessa da vendedora do o especialista, por enquanto as duas ações que me passaram foi construir reserva e vender o apartamento, não precisa do programa pra saber disso', NULL, 'O programa parece interessante, no entanto meu perfil e momento não se adequam ao programa, entrei especialmente com o objetivo de alavancar o imóvel, como foi prometido que mesmo sem reserva para lance seria possível contemplar, acreditei na promessa e por enquanto não está tendo utilidade alguma.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', '6mit0a3ll0lqiv4936mito0sv17ma715', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_