INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('d6pv9agiefmnlb8n5hd6pvwa5mdz00sc', '2025-Q2', 'Jun/2025', '2025-06-13T10:06'::timestamptz, 'Sergio Bugy', 'sergio bugy', 'PHARUS', 'Junior Teixeira', 0.0, 'Detrator', 2.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Tenho clareza e estou executando com consistência', 'Não tive resposta das minhas necessidades, além do programa ser muito raso nas opções que dão para investimentos. Depois de mais de 6 meses nunca tive um plano de verdade.', 'Primeiro um plano de verdade, com início meio e fim. Depois opções melhores de investimentos. A única opção diferente que deram foi em um investimento no escuro que promete rendimento alto mas com 2 meses com o dinheiro parado em caso de resgate. E mesmo assim, se vc colocar na conta o custo da assessoria, no fim ficaria elas por elas. Muito fraco, pelo que prometiam nas lives.', NULL, 'O básico é conseguir recuperar o valor pago na assessoria. Se tô pagando por uma assessoria financeira e no fim saio mais pobre com ela do q sem, não dá nem pra pensar em continuar. Mas precisava mesmo de produtos melhores. Ficaram só na conversa, colocar dinheiro em fundo D0 e comprar estúdio é o q todo mundo q pesquisa um pouquinho faz. Não precisava de assessor pra isso.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'd6pv9agiefmnlb8n5hd6pvwa5mdz00sc', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
