INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('83z9cjjzg6ybldlllg7183z9cjjzb8zb', '2025-Q3', 'Out/2025', '2025-10-02T11:00'::timestamptz, 'Leandro Pincinato', 'leandro pincinato', 'PHARUS', 'Rafael Pracz', 8.0, 'Neutro', 7.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'Os resultados são de médio longo prazo então ainda não consigo avaliar a performance das recomendações', 'Algumas promessas não foram cumpridas. Por mais de uma vez foi prometido fazer uma revisão dos meus seguros e essa revisão não ocorreu. Além disso, as aulas ensinando os fundamentos de cada estratégia, que foram prometidas no lançamento, ainda não foram disponibilizadas. Outro ponto é a atualização mensal do fluxo de caixa que da bastante trabalho pra fazer.', NULL, 'Ter resultados financeiros claros e tangíveis.', 'O projeto é muito legal, acredito no potencial. A execução ainda necessita de ajustes.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '83z9cjjzg6ybldlllg7183z9cjjzb8zb', 'NPS (PHARUS) (111 dias)', 'NPS (PHARUS)') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_pa