INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('c21nu559oijycaac21nlguthbpmwaq3o', '2025-Q3', 'Out/2025', '2025-10-21T09:45'::timestamptz, 'Lourival Rech Junior', 'lourival rech junior', 'PHARUS', 'Samuel Araújo', 6.0, 'Detrator', 7.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'Demora em receber acesso aos conteúdos logo após a compra. Não há uma área onde todos os conteúdos ficam disponíveis para fácil consulta. O formato do diagnóstico entregue é de difícil leitura, não deixando claro uma sequência de ações a ser realizadas. As recomendações de investimento somente em São Paulo causa certa insegurança para quem está em outras cidades distantes e não consegue visitar os empreendimentos.', 'Liberar o acessos aos conteúdos de forma mais rápida após a compra. Ter uma área onde os conteúdos ficam disponíveis de forma organizada. Estruturar melhor o documento de diagnóstico, para facilitar a conexão entre as diversas ações e dar uma visão de longo prazo da construção de patrimônio. Fornecer mais informações sobre os empreendimentos em São Paulo para aumentar a segurança de quem é de cidades distantes e não consegue visitar os empreendimentos presencialmente.', NULL, 'Ter um plano claro do que precisa ser feito a cada trimestre e precisa ser implementado a cada ano, com um fluxo de caixa claro das entradas e saídas.', 'Não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'c21nu559oijycaac21nlguthbpmwaq3o', 'cadastro 2026-T2 (266 dias)', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
